  /** clear: no entry at or above the threshold · possible_match: review the hits */
  outcome: "clear" | "possible_match";
  /** none (clear) · pending (a hit is not decided yet) · cleared (every hit: not the same person) · confirmed (a hit is the same person) */
  review: "none" | "pending" | "cleared" | "confirmed";
