/** Up to 500 transactions. Each is checked on its own: a refused one never stops the others. */
export type TransactionBatchRequest = {
  transactions: Array<TransactionInput>;
};

export type TransactionBatchResult = {
  id: string;
  object: "transaction_batch";
  environment: "test" | "live";
  received: number;
  created: number;
  duplicates: number;
  /** Status moves (pending → completed …) */
  updated: number;
  conflicts: number;
  rejected: number;
  results: Array<{
    index: number;
    transaction_id: string | null;
    result: "created" | "duplicate" | "updated" | "conflict" | "rejected";
    /** Our id (txn_…) — null when refused */
    id: string | null;
    error: TransactionItemError | null;
  }>;
  /** What your monitoring rules did with the new transactions (step 9.2): alerts raised and updated. null: they could not run now — the transactions are stored and the next batch runs them again. */
  alerts: {
    raised: number;
    updated: number;
  } | null;
  duration_ms: number;
};

export type TransactionInput = {
  /** YOUR id for the transaction — unique in the environment. Sending the same id again is safe: the same content is a duplicate, a new status moves the status, anything else is refused as a conflict. */
  id: string;
  /** When it happened (ISO 8601 with a time zone). Up to five years back. */
  occurred_at: string;
  /** transfer · deposit · withdrawal · payment · card_payment · cash · crypto_deposit · crypto_withdrawal · trade · exchange · loan · refund · fee · other */
  type: "transfer" | "deposit" | "withdrawal" | "payment" | "card_payment" | "cash" | "crypto_deposit" | "crypto_withdrawal" | "trade" | "exchange" | "loan" | "refund" | "fee" | "other";
  /** inbound: money comes TO your customer · outbound: it leaves your customer · internal: between their own accounts */
  direction: "inbound" | "outbound" | "internal";
  /** The amount in `currency`, as a string so no digit is lost (up to 18 decimals). */
  amount: string | number;
  currency: string;
  /** Optional: the same amount in your reporting currency, as YOUR books convert it. Compliwa never converts currencies itself. */
  value?: {
    amount: string | number;
    currency: string;
  };
  /**
   * pending → completed or failed; completed → reversed. Default completed.
   *
   * Default: "completed"
   */
  status?: "pending" | "completed" | "failed" | "reversed";
  /** bank_transfer · card · mobile_money · cash · crypto · ussd · pos · wallet · cheque · other */
  channel?: "bank_transfer" | "card" | "mobile_money" | "cash" | "crypto" | "ussd" | "pos" | "wallet" | "cheque" | "other";
  /** Your customer — the account the money moved on */
  customer: {
    /** Your reference for the customer — never personal data. Required. */
    reference: string;
    /** person · business · unknown */
    type?: "person" | "business" | "unknown";
    country?: string;
  };
  /** The other side, when known */
  counterparty?: {
    /** Stored encrypted */
    name?: string;
    /** Account number, IBAN, card token or wallet address — stored encrypted, with a blind index so the same counterparty is recognised later */
    account?: string;
    institution?: string;
    /** person · business · unknown */
    type?: "person" | "business" | "unknown";
    country?: string;
  };
  /** Narration or memo — stored encrypted */
  description?: string;
  /** Where the request came from, when you know it */
  ip_country?: string;
  /** Your own labels (product, branch, campaign…), up to 20 keys. Never personal data — it is stored in clear. */
  metadata?: {
    [key: string]: string | number | boolean;
  };
};

export type TransactionItemError = {
  /** Position in the batch (0 = the first) or the file row (1 = the first data row) */
  index: number;
  transaction_id: string | null;
  /** invalid · occurred_at_out_of_range · transaction_conflict (same id, other content) · status_move_not_allowed */
  code: string;
  field: string | null;
  message: string;
};

