export type VerificationRequest = {
  /** Which ID: COUNTRY:TYPE — NG:NIN · NG:BVN · NG:PASSPORT · NG:DRIVERS_LICENSE · NG:VOTER_ID · GH:GHANA_CARD · KE:NATIONAL_ID · ZA:NATIONAL_ID */
  check: "NG:NIN" | "NG:BVN" | "NG:PASSPORT" | "NG:DRIVERS_LICENSE" | "NG:VOTER_ID" | "GH:GHANA_CARD" | "KE:NATIONAL_ID" | "ZA:NATIONAL_ID";
  id_number: string;
  /** Compared with the record (our own match) */
  first_name?: string;
  last_name?: string;
  date_of_birth?: string;
  /** Your own reference for this person — never personal data */
  reference?: string;
  /** The person agreed to this check. Compliwa records the consent (step 8.6) against your identity_check notice — or `consent_notice` — and links it to the check. Give this or `consent_id`: Compliwa never checks anyone without consent. */
  consent?: true;
  /** A consent you already recorded (POST /v1/consents) — active, for the same person, covering identity_verification */
  consent_id?: string;
  /** With consent: true — the notice the person saw (a key or a cnv_ version ID); by default identity_check */
  consent_notice?: string;
  /** With consent: true — when the person agreed, if earlier (up to 30 days ago) */
  consent_given_at?: string;
  /** With consent: true — the language the person read the notice in */
  consent_language?: "en" | "fr" | "es" | "ar";
  /**
   * Return the photo on the record (in this answer only — Compliwa never stores it)
   *
   * Default: false
   */
  include_photo?: boolean;
};

